insert into public.mg628_lab_questions (lab, id, module, kind, body) values
  ('regression','m1q1','m1','static',$q${"stem": "Which statement best describes regression?", "opts": ["It proves which factors cause an outcome", "It estimates how an outcome changes with one or more predictors, with a measure of uncertainty", "It summarizes the spread of a single variable", "It groups similar records together"], "ans": 1, "why": "Regression estimates relationships and their uncertainty. Whether a relationship is causal depends on how the data were generated."}$q$::jsonb),
  ('regression','m1q2','m1','static',$q${"stem": "Riverside County models processing days from caseworker ratio and digital access. In this model, the caseworker ratio is:", "opts": ["The outcome", "A predictor", "The residual", "The intercept"], "ans": 1, "why": "Processing days is the outcome; caseworker ratio is one of the drivers, a predictor."}$q$::jsonb),
  ('regression','m1q3','m1','static',$q${"stem": "Which step should come before fitting a model?", "opts": ["Reporting prediction intervals", "Testing the model on held-out data", "Plotting the outcome against each predictor", "Writing the recommendation"], "ans": 2, "why": "Explore first: plots reveal direction, shape and unusual points before any coefficients are estimated."}$q$::jsonb),
  ('regression','m1q4','m1','static',$q${"stem": "Why does the predictive-modeling loop 'close'?", "opts": ["Because a model is final once it is fit", "Because the outcomes of decisions become new data used to check and refit the model", "Because predictions replace the need for data", "Because the intercept resets each cycle"], "ans": 1, "why": "A model never checked against what actually happened should not be trusted. Outcomes feed back into the next fit."}$q$::jsonb),
  ('regression','m1q5','m1','static',$q${"stem": "A model will be judged by how close its forecasts come to next quarter's actual sales. Its primary job is:", "opts": ["Explanation", "Prediction", "Description", "Classification"], "ans": 1, "why": "When success is measured by accuracy on future cases, the job is prediction."}$q$::jsonb),
  ('regression','m1q6','m1','static',$q${"stem": "A hospital models length of stay from patient age and ICU admission. Which is the outcome?", "opts": ["Length of stay", "Patient age", "ICU admission", "The hospital"], "ans": 0, "why": "The outcome is what the model explains or forecasts; age and ICU admission are predictors."}$q$::jsonb),
  ('regression','m1q7','m1','static',$q${"stem": "Which of these is an explanation question?", "opts": ["Does weekend discharge raise readmission risk once patient complexity is accounted for?", "What will revenue be next quarter?", "How many leads will next month's campaign produce?", "How many applications will arrive next week?"], "ans": 0, "why": "Explanation asks how much a driver moves the outcome, holding others constant. The others ask for a forecast."}$q$::jsonb),
  ('regression','m1q8','m1','static',$q${"stem": "Which step of the modeling process turns coefficients into dollars, days or patients with an honest range?", "opts": ["Communicate and act", "Explore", "Gather and clean", "Fit"], "ans": 0, "why": "Communicating translates results into managerial units with uncertainty, so a decision can follow."}$q$::jsonb),
  ('regression','m2q1','m2','static',$q${"stem": "Ordinary least squares chooses the line that minimizes:", "opts": ["The sum of the residuals", "The sum of squared residuals", "The largest single residual", "The number of points off the line"], "ans": 1, "why": "Squared residuals can't cancel, and large misses count more."}$q$::jsonb),
  ('regression','m2q2','m2','static',$q${"stem": "The 95% CI for the slope is 11.9 to 19.0 leads per $1,000. The best conclusion is:", "opts": ["Spend causes between 11.9 and 19.0 leads", "The effect is plausibly between about 12 and 19 leads per $1,000, and clearly above zero", "95% of campaigns fall in that range", "The slope is not significant"], "ans": 1, "why": "The interval gives plausible values for the average effect. Zero is far outside it."}$q$::jsonb),
  ('regression','m2q3','m2','static',$q${"stem": "If one dollar buys 0.01546 leads, the cost of one additional lead is about:", "opts": ["$0.015", "$15.46", "$38", "$65"], "ans": 3, "why": "1 ÷ 0.01546 ≈ $65 per additional lead, compared with a $38 average."}$q$::jsonb),
  ('regression','m2q4','m2','static',$q${"stem": "In a log-log model the slope is 0.70. A 10% increase in spend is associated with:", "opts": ["10% more leads", "About 7% more leads", "70% more leads", "0.7 more leads"], "ans": 1, "why": "The slope is an elasticity: 1.10^0.70 ≈ 1.069, about 6.9% more leads."}$q$::jsonb),
  ('regression','m2q5','m2','static',$q${"stem": "NovaTech sets its largest budgets in peak season. Why does this threaten a causal reading of the slope?", "opts": ["The sample is too small", "Season may drive both spend and leads", "R² is below 0.7", "The intercept is outside the data"], "ans": 1, "why": "A confounder that moves both variables makes part of the slope belong to it, not to spend."}$q$::jsonb),
  ('regression','m2_predict','m2','gen',$q${"gen": "m2_predict"}$q$::jsonb),
  ('regression','m2_change','m2','gen',$q${"gen": "m2_change"}$q$::jsonb),
  ('regression','m2_marginal','m2','gen',$q${"gen": "m2_marginal"}$q$::jsonb),
  ('regression','m2_elastic','m2','gen',$q${"gen": "m2_elastic"}$q$::jsonb),
  ('regression','m3q1','m3','static',$q${"stem": "You add a predictor that has no real relationship with the outcome. What typically happens?", "opts": ["R² falls and adjusted R² rises", "R² stays the same or rises slightly; adjusted R² may fall", "Both R² and adjusted R² rise sharply", "The intercept becomes zero"], "ans": 1, "why": "R² never falls when a predictor is added. Adjusted R² penalizes predictors that don't earn their place."}$q$::jsonb),
  ('regression','m3q2','m3','static',$q${"stem": "A predictor has a VIF of 12. What does that indicate?", "opts": ["No overlap with other predictors", "Severe multicollinearity: its standard error is inflated", "The predictor is highly significant", "The model is overfitting"], "ans": 1, "why": "Above 10 is severe overlap; coefficients become unstable and look less significant."}$q$::jsonb),
  ('regression','m3q3','m3','static',$q${"stem": "In Mercy Regional's model, P(readmit) = 0.084 + 0.0066 × chronic conditions. An extra chronic condition is associated with:", "opts": ["0.0066% higher risk", "0.66 percentage points higher risk", "6.6% higher risk", "8.4% higher risk"], "ans": 1, "why": "In a linear probability model, 0.0066 is a change in probability: 0.66 percentage points."}$q$::jsonb),
  ('regression','m3q4','m3','static',$q${"stem": "The chronic-conditions effect has p = 0.0001 but patient-level R² = 0.001. What follows?", "opts": ["The finding is an error", "The effect is real but explains little of individual variation", "The model is overfit", "The predictor should be removed"], "ans": 1, "why": "Individual readmissions are noisy. The model describes average risk well and individual outcomes poorly."}$q$::jsonb),
  ('regression','m3q5','m3','static',$q${"stem": "Riverside's digital-access % is measured per district and shared by every applicant in it. Its effective sample size is closer to:", "opts": ["The number of applications", "The number of districts", "The number of programs", "The number of caseworkers"], "ans": 1, "why": "A district-level value repeats for every applicant, so it carries only as much information as there are districts."}$q$::jsonb),
  ('regression','m3_dummies','m3','gen',$q${"gen": "m3_dummies"}$q$::jsonb),
  ('regression','m3_coef','m3','gen',$q${"gen": "m3_coef"}$q$::jsonb),
  ('regression','m3_lpm','m3','gen',$q${"gen": "m3_lpm"}$q$::jsonb),
  ('regression','m3_vif','m3','gen',$q${"gen": "m3_vif"}$q$::jsonb),
  ('regression','m4q1','m4','static',$q${"stem": "Heteroscedasticity mainly affects:", "opts": ["Whether the coefficients are unbiased", "The standard errors, p-values and confidence intervals", "The value of R²", "The number of observations"], "ans": 1, "why": "Coefficients remain unbiased; inference becomes unreliable."}$q$::jsonb),
  ('regression','m4q2','m4','static',$q${"stem": "A Durbin–Watson statistic of 1.97 suggests:", "opts": ["Strong positive autocorrelation", "No evidence that errors are correlated", "Unequal variance", "Non-normal residuals"], "ans": 1, "why": "Values near 2 indicate independent errors."}$q$::jsonb),
  ('regression','m4q3','m4','static',$q${"stem": "An events campaign produced far more leads than predicted and is highly influential. The best first response is:", "opts": ["Delete it so the model fits better", "Verify the data, understand why, and report results with and without it", "Ignore it because n is small", "Replace it with the average"], "ans": 1, "why": "Influential points are evidence. Check them, explain them, and show their effect."}$q$::jsonb),
  ('regression','m4q4','m4','static',$q${"stem": "Length of stay has mean 4.5 days, median 3 and skewness 1.97. A sensible modeling step is:", "opts": ["Delete the long stays", "Model log(length of stay)", "Add more predictors until skew disappears", "Use the median as the outcome"], "ans": 1, "why": "A log transform pulls in the long tail; coefficients become percentage effects."}$q$::jsonb),
  ('regression','m4q5','m4','static',$q${"stem": "NovaTech's residuals show mild non-normality (Jarque–Bera p = 0.0002) with n = 1,200. This is:", "opts": ["Fatal: the model is invalid", "A minor concern, because large samples protect coefficient tests", "Proof of heteroscedasticity", "A sign of multicollinearity"], "ans": 1, "why": "The central limit theorem makes coefficient tests robust to mild non-normality in large samples."}$q$::jsonb),
  ('regression','m4_cooks','m4','gen',$q${"gen": "m4_cooks"}$q$::jsonb),
  ('regression','m4_dw','m4','gen',$q${"gen": "m4_dw"}$q$::jsonb),
  ('regression','m4_log','m4','gen',$q${"gen": "m4_log"}$q$::jsonb),
  ('regression','m5q1','m5','static',$q${"stem": "Model A: training RMSE $2,900, test RMSE $5,800. This pattern indicates:", "opts": ["Underfitting", "Overfitting", "A perfect model", "Heteroscedasticity"], "ans": 1, "why": "Error that doubles on new data is the signature of memorizing training noise."}$q$::jsonb),
  ('regression','m5q2','m5','static',$q${"stem": "Compared with MAE, RMSE:", "opts": ["Ignores large errors", "Penalizes large errors more heavily", "Is always smaller", "Has no units"], "ans": 1, "why": "Squaring errors before averaging gives big misses more weight."}$q$::jsonb),
  ('regression','m5q3','m5','static',$q${"stem": "What can Lasso do that Ridge cannot?", "opts": ["Shrink coefficients toward zero", "Set some coefficients exactly to zero", "Increase R² on training data", "Remove the intercept"], "ans": 1, "why": "Lasso's penalty can zero out coefficients, which selects predictors."}$q$::jsonb),
  ('regression','m5q4','m5','static',$q${"stem": "Why use 5-fold cross-validation instead of one split on 48 campaigns?", "opts": ["It uses fewer data", "It removes dependence on which cases happen to land in the test set", "It guarantees a higher R²", "It avoids fitting the model"], "ans": 1, "why": "Rotating the test fold averages away the luck of a single split."}$q$::jsonb),
  ('regression','m5q5','m5','static',$q${"stem": "NovaTech's test MAE is $2,705 and the average deal brings $33,745 a month. A typical forecast misses by about:", "opts": ["0.8%", "8%", "27%", "80%"], "ans": 1, "why": "2,705 ÷ 33,745 ≈ 0.08."}$q$::jsonb),
  ('regression','m5_mae','m5','gen',$q${"gen": "m5_mae"}$q$::jsonb),
  ('regression','m5_rmse','m5','gen',$q${"gen": "m5_rmse"}$q$::jsonb),
  ('regression','m5_pct','m5','gen',$q${"gen": "m5_pct"}$q$::jsonb),
  ('regression','m5_fit','m5','gen',$q${"gen": "m5_fit"}$q$::jsonb),
  ('regression','m6q1','m6','static',$q${"stem": "In statsmodels, what does C(Region) in a formula do?", "opts": ["Centers the variable", "Treats Region as categorical and builds dummy variables", "Removes Region from the model", "Computes a correlation"], "ans": 1, "why": "C() marks a column as categorical; statsmodels creates the k − 1 dummies."}$q$::jsonb),
  ('regression','m6q2','m6','static',$q${"stem": "In Excel's regression output, Significance F is:", "opts": ["The R² of the model", "The p-value for the model as a whole", "The slope's standard error", "The number of observations"], "ans": 1, "why": "It tests whether all predictors together explain anything."}$q$::jsonb),
  ('regression','m6q3','m6','static',$q${"stem": "Why is a prediction interval wider than a confidence interval for the same forecast?", "opts": ["It uses a lower confidence level", "It includes the individual variation the model cannot explain", "It ignores the slope", "It is computed on test data"], "ans": 1, "why": "Averages cancel noise; a single case does not."}$q$::jsonb),
  ('regression','m6q4','m6','static',$q${"stem": "Which statement belongs in the Risk step of the recommendation chain?", "opts": ["The slope is 15.5 leads per $1,000", "Cap spend where a lead is worth less than $65", "Budgets may follow the season, and returns may differ by channel", "The next lead costs about $65"], "ans": 2, "why": "Risk names what could make the conclusion wrong."}$q$::jsonb),
  ('regression','m6q5','m6','static',$q${"stem": "A colleague says “p < 0.05, so the effect is large.” The best correction is:", "opts": ["Agree: small p means large effect", "Small p means the effect is distinguishable from zero; size is the coefficient in real units", "Small p means R² is high", "Small p proves causation"], "ans": 1, "why": "Significance and size are different questions. Report the effect in dollars, days or patients."}$q$::jsonb),
  ('regression','m6_interval','m6','gen',$q${"gen": "m6_interval"}$q$::jsonb),
  ('regression','m6_chain','m6','gen',$q${"gen": "m6_chain"}$q$::jsonb);
